class Solution {
public:
    long long minimumCost(string s) {
        long long n = s.size(), ans = 0;
        for (int i = 0; i + 1 < n; i++)
            if (s[i] != s[i + 1]) ans += min(i + 1, n - i - 1);
        return ans;
    }
};

